public class Equiv {
  static double oldClamp(double value){ // original PairedStats hand-rolled
    if (value >= 1.0) return 1.0;
    if (value <= -1.0) return -1.0;
    return value;
  }
  static double newClamp(double value){ // Doubles.constrainToRange(value,-1,1)
    return Math.min(Math.max(value, -1.0), 1.0);
  }
  public static void main(String[] a){
    double[] xs = {Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY,
      0.0, -0.0, 1.0, -1.0, 0.9999999999, 1.0000000001, -0.9999999999, -1.0000000001,
      0.5, -0.5, Double.MIN_VALUE, -Double.MIN_VALUE, Double.MAX_VALUE, -Double.MAX_VALUE};
    int fail=0;
    for(double x: xs){
      long o=Double.doubleToRawLongBits(oldClamp(x)), n=Double.doubleToRawLongBits(newClamp(x));
      if(o!=n){ System.out.printf("MISMATCH x=%s old=%s new=%s%n", x, oldClamp(x), newClamp(x)); fail++; }
    }
    System.out.println(fail==0 ? "BIT-EXACT EQUIVALENT (all "+xs.length+" cases)" : "FAILURES="+fail);
